mapper.sql:
select
    ,
    ,
    parent_pkg.package_code as parent_code
from wm_package
left join wm_package parent_pkg on parent_pkg.package_id = wm_package.parent_id

    wm_package.del_flag = '0'
     and wm_package.package_id = #{packageId}

        and wm_package.package_code like concat('%', #{packageCode}, '%')

     and wm_package.client_id = #{clientId}

        and wm_package.so_code like concat('%', #{soCode}, '%')

     and wm_package.status = #{status}
     and wm_package.parent_id = #{parentId}

         and wm_package.package_date >= #{packageDateStart} 


         and wm_package.package_date <= #{packageDateEnd} 


order by wm_package.package_id desc

mapper.select:
select count(*) from wm_package
where package_code = #{packageCode} and del_flag = '0'
 and package_id != #{excludeId}

mapper.update:
update wm_package
set status = #{toStatus}, update_time = now()
where package_id = #{packageId}
  and status = #{fromStatus}
  and del_flag = '0'

update wm_package
set del_flag = '1', update_time = now()
where package_id = #{packageId}
